//go:build amd64

package floats

// Add32, Sub32, Mul32, Div32 and Sqrt32 kernels (binop32.go), generated by
// go-asmgen (binop32_amd64_gen.go) into binop32_amd64.s. The callers pass every
// slice already sliced to the common length. The AVX2 kernels share the gate of
// the other AVX2 kernels (hasAVX2FMA, kernels_amd64.go) and use no FMA; on a CPU
// without AVX2+FMA the SSE2 kernels (the amd64 baseline) run, with identical
// results. No kernel keeps a pointer: every stub is go:noescape.
//
//go:noescape
func add32AVX2(dst, a, b []float32)

//go:noescape
func sub32AVX2(dst, a, b []float32)

//go:noescape
func mul32AVX2(dst, a, b []float32)

//go:noescape
func div32AVX2(dst, a, b []float32)

//go:noescape
func sqrt32AVX2(dst, src []float32)

//go:noescape
func add32SSE2(dst, a, b []float32)

//go:noescape
func sub32SSE2(dst, a, b []float32)

//go:noescape
func mul32SSE2(dst, a, b []float32)

//go:noescape
func div32SSE2(dst, a, b []float32)

//go:noescape
func sqrt32SSE2(dst, src []float32)

// binop32SSEFrom is the length from which Add32, Sub32 and Mul32 use the SSE2
// kernel even when AVX2 is available. Past the L2 cache (three float32 streams of
// 65536 elements are 768 KiB) these loops are bound by memory, not by the vector
// unit, and on Zen 3 the 128-bit loop moves the data 7-10 % faster than the
// 256-bit one (EPYC 7773X, BenchmarkBinop32Variants: Add32 n=65536 9.7 us vs
// 10.5 us, n=1e6 165 us vs 181 us; below 32768 the AVX2 kernel is as fast or up
// to 2.3x faster). Neither a different unroll depth nor a 32-byte aligned
// destination closed the gap. Div32 is bound by the divider, where the AVX2
// kernel wins at every length, so it has no threshold. Results are bit-identical
// either way (one IEEE operation per lane).
const binop32SSEFrom = 1 << 16

func add32(dst, a, b []float32) {
	if hasAVX2FMA && len(dst) < binop32SSEFrom {
		add32AVX2(dst, a, b)
		return
	}
	add32SSE2(dst, a, b)
}

func sub32(dst, a, b []float32) {
	if hasAVX2FMA && len(dst) < binop32SSEFrom {
		sub32AVX2(dst, a, b)
		return
	}
	sub32SSE2(dst, a, b)
}

func mul32(dst, a, b []float32) {
	if hasAVX2FMA && len(dst) < binop32SSEFrom {
		mul32AVX2(dst, a, b)
		return
	}
	mul32SSE2(dst, a, b)
}

func div32(dst, a, b []float32) {
	if hasAVX2FMA {
		div32AVX2(dst, a, b)
		return
	}
	div32SSE2(dst, a, b)
}

func sqrt32(dst, src []float32) {
	if hasAVX2FMA {
		sqrt32AVX2(dst, src)
		return
	}
	sqrt32SSE2(dst, src)
}
